/**
 * Exports of h3 1.15.11 that h3 2.0.8 no longer has, with the replacement the H3 migration guide
 * (https://h3.dev/migration) names, checked against 2.0.8's exports. 2.0.1-rc.26 lacks all of them too.
 *
 * Generated by diffing export names, then sorting each side with `LC_ALL=C sort`:
 * - values: `Object.keys(await import("h3@1.15.11/dist/index.mjs"))` minus
 *   `Object.keys(await import("h3@2.0.8/dist/_entries/node.mjs"))` (every 2.0.8 entry exports the
 *   same names);
 * - types: the names `checker.getExportsOfModule()` gives for `h3@1.15.11/dist/index.d.ts`, minus
 *   the 1.15.11 runtime values, minus the names it gives for `h3@2.0.8/dist/_entries/generic.d.mts`.
 *
 * `null` means the guide names no replacement and 2.0.8 has none.
 */
export const removedH3Values: ReadonlyMap<string, string | null> = new Map([
  ["H3Headers", "Use the native Headers class."],
  ["H3Response", "Use the native Response class."],
  ["MIMES", 'Write the MIME type string, such as "application/json".'],
  ["callNodeListener", "Wrap the Node.js listener with fromNodeHandler()."],
  ["createAppEventHandler", "Use the handler or fetch method of new H3()."],
  ["createEvent", "Serve the app through the Node.js adapter, toNodeHandler(app)."],
  [
    "defineRequestMiddleware",
    "Wrap the hook with onRequest() and pass it in the handler's middleware array.",
  ],
  [
    "defineResponseMiddleware",
    "Wrap the hook with onResponse(), which calls it with (response, event), and pass it in the handler's middleware array.",
  ],
  ["fromPlainHandler", "Write a Web API handler and wrap it with fromWebHandler()."],
  ["isEventHandler", 'Any function is an event handler; check typeof value === "function".'],
  ["isStream", "Check value instanceof ReadableStream."],
  ["isWebResponse", "Check value instanceof Response."],
  ["promisifyNodeListener", "Wrap the Node.js listener with fromNodeHandler()."],
  ["send", "Return the response value from the handler."],
  ["sendError", "Throw an HTTPError from the handler."],
  ["splitCookiesString", "Use splitSetCookieString() from cookie-es."],
  ["toPlainHandler", "Use the app's fetch method, which takes a Request and returns a Response."],
  ["toWebRequest", "Read event.req, which is already a Web Request."],
  ["use", "Call app.use() on the H3 app."],
]);

